CREATE TABLE IF NOT EXISTS public.image_backfill_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_image_id uuid NOT NULL REFERENCES public.product_images(id) ON DELETE CASCADE, cloudflare_image_id varchar(100) NOT NULL, url_cdn text NOT NULL, format varchar(20), task text NOT NULL CHECK (task IN ('blurhash','content_hash','file_size','dimensions','reupload')), priority smallint NOT NULL DEFAULT 5, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','done','failed','skipped')), attempts smallint NOT NULL DEFAULT 0, last_error text, worker_id text, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, CONSTRAINT uq_backfill_one_per_image_task UNIQUE (product_image_id, task)); CREATE INDEX IF NOT EXISTS idx_backfill_queue_dispatch ON public.image_backfill_queue (priority DESC, created_at ASC) WHERE status = 'pending'; CREATE INDEX IF NOT EXISTS idx_backfill_queue_by_task ON public.image_backfill_queue (task, status); COMMENT ON TABLE public.image_backfill_queue IS 'Fila de backfill de metadados (blurhash, hash, dims, file_size, reupload). 2026-06-17 — Claude.';;
